/**
 * OCR accuracy on rendered songbook pages (tests/fixtures/ocr, generated by
 * scripts/render-fixtures.mjs). Runs the same recipe as the app (core/ocr/pipeline) with the
 * Node build of tesseract.js and the bundled traineddata – fully offline.
 *
 *   npm run test:ocr
 *
 * Env overrides for experiments: OCR_LANGS=ces,eng  OCR_PSM=6
 */
import { copyFileSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, resolve } from 'node:path'
import { PNG } from 'pngjs'
import { createWorker, type Worker, type WorkerParams } from 'tesseract.js'
import type { Rgba } from '../ocr/image'
import {
  OCR_ENGINE_MODE,
  OCR_LANGUAGES,
  OCR_PAGE_PARAMS,
  ocrPage,
  type TesseractWorkerLike
} from '../ocr/pipeline'
import { wordsToText } from './layout'

const ROOT = resolve(import.meta.dirname, '../../..')
const FIXTURES = join(ROOT, 'tests/fixtures/ocr')
const TEXT_TARGET = 0.97
const CHORD_TARGET = 0.9

// ---------------------------------------------------------------------------------------------
// Metrics

const CHORD_RE = /\[([^\]]*)\]/g

/** Lyrics without chords: lines joined, whitespace runs collapsed. */
function lyricsNoChords(text: string): string {
  return text.replace(CHORD_RE, '').replace(/\s+/g, ' ').trim()
}

/** Chords with their position in the chord-free text (lines kept, so positions are comparable). */
function chordsWithPositions(text: string): { plain: string; chords: Array<{ name: string; pos: number }> } {
  const chords: Array<{ name: string; pos: number }> = []
  let plain = ''
  let last = 0
  for (const m of text.matchAll(CHORD_RE)) {
    plain += text.slice(last, m.index)
    chords.push({ name: m[1]!, pos: plain.length })
    last = (m.index ?? 0) + m[0].length
  }
  plain += text.slice(last)
  return { plain, chords }
}

function levenshtein(a: string, b: string): number {
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j)
  for (let i = 1; i <= a.length; i++) {
    const cur = [i]
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j]! + 1, cur[j - 1]! + 1, prev[j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1))
    }
    prev = cur
  }
  return prev[b.length]!
}

/** For every index 0..a.length of `a`, the aligned index in `b` (minimum edit alignment). */
function alignIndices(a: string, b: string): number[] {
  const n = a.length
  const m = b.length
  const d: Uint32Array[] = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1))
  for (let j = 0; j <= m; j++) d[0]![j] = j
  for (let i = 1; i <= n; i++) {
    d[i]![0] = i
    for (let j = 1; j <= m; j++) {
      d[i]![j] = Math.min(
        d[i - 1]![j]! + 1,
        d[i]![j - 1]! + 1,
        d[i - 1]![j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1)
      )
    }
  }
  const map = new Array<number>(n + 1).fill(0)
  let i = n
  let j = m
  map[n] = m
  while (i > 0) {
    if (j > 0 && d[i]![j] === d[i - 1]![j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1)) {
      i--
      j--
    } else if (d[i]![j] === d[i - 1]![j]! + 1) {
      i--
    } else {
      j--
      continue
    }
    map[i] = j
  }
  return map
}

/** 1 − Levenshtein / length of the truth lyrics (chords removed). */
function textAccuracy(pred: string, truth: string): number {
  const t = lyricsNoChords(truth)
  return 1 - levenshtein(lyricsNoChords(pred), t) / t.length
}

/** Share of truth chords that the prediction has with the same name within ±1 character. */
function chordAccuracy(pred: string, truth: string): { score: number; missed: string[] } {
  const p = chordsWithPositions(pred)
  const t = chordsWithPositions(truth)
  const map = alignIndices(t.plain, p.plain)
  const used = new Set<number>()
  const missed: string[] = []
  for (const chord of t.chords) {
    const at = map[chord.pos]!
    const hit = p.chords.findIndex(
      (c, i) => !used.has(i) && c.name === chord.name && Math.abs(c.pos - at) <= 1
    )
    if (hit >= 0) used.add(hit)
    else missed.push(`${chord.name}@"${t.plain.slice(chord.pos, chord.pos + 8).replace(/\n/g, '⏎')}"`)
  }
  return { score: t.chords.length ? (t.chords.length - missed.length) / t.chords.length : 1, missed }
}

describe('accuracy metrics (sanity)', () => {
  it('scores a perfect prediction as 1', () => {
    const truth = 'Název\n\n1. [G]Text pr[D]vní sloky'
    expect(textAccuracy(truth, truth)).toBe(1)
    expect(chordAccuracy(truth, truth).score).toBe(1)
  })
  it('tolerates a chord one character off but not two', () => {
    const truth = '[G]Text pr[D]vní sloky'
    expect(chordAccuracy('[G]Text p[D]rvní sloky', truth).score).toBe(1)
    expect(chordAccuracy('[G]Text [D]první sloky', truth).score).toBe(0.5)
    expect(chordAccuracy('[G]Text pr[A]vní sloky', truth).score).toBe(0.5)
  })
  it('aligns chord positions across OCR character errors', () => {
    const truth = 'Zář nad [G]námi\nsvětlo [D]věčné'
    expect(chordAccuracy('Zar nad [G]nami\nsvetlo [D]vecne', truth).score).toBe(1)
    expect(textAccuracy('Zar nad nami svetlo vecne', truth)).toBeCloseTo(1 - 7 / 25, 5)
  })
})

// ---------------------------------------------------------------------------------------------
// OCR run

const fixtures = readdirSync(FIXTURES)
  .filter((f) => f.endsWith('.png'))
  .map((f) => f.replace(/\.png$/, ''))
  .sort()

let worker: Worker
let tmp: string

function readRgba(path: string): Rgba {
  const png = PNG.sync.read(readFileSync(path))
  return { width: png.width, height: png.height, data: new Uint8ClampedArray(png.data) }
}

function encodePng(img: Rgba): Buffer {
  const png = new PNG({ width: img.width, height: img.height })
  png.data = Buffer.from(img.data.buffer, img.data.byteOffset, img.data.byteLength)
  return PNG.sync.write(png)
}

const langs = process.env.OCR_LANGS ? process.env.OCR_LANGS.split(',') : OCR_LANGUAGES

beforeAll(async () => {
  tmp = mkdtempSync(join(tmpdir(), 'promitac-ocr-'))
  const langPath = join(tmp, 'lang')
  mkdirSync(langPath)
  for (const lang of ['ces', 'eng']) {
    const gz = `${lang}.traineddata.gz`
    copyFileSync(
      join(ROOT, `node_modules/@tesseract.js-data/${lang}/4.0.0_best_int/${gz}`),
      join(langPath, gz)
    )
  }
  const t0 = performance.now()
  worker = await createWorker(langs, OCR_ENGINE_MODE, { langPath, cachePath: tmp, gzip: true })
  console.log(`[ocr] worker ready (${langs.join('+')}) in ${Math.round(performance.now() - t0)} ms`)
})

afterAll(async () => {
  await worker?.terminate()
  if (tmp) rmSync(tmp, { recursive: true, force: true })
})

describe('OCR accuracy on rendered songbook pages', () => {
  it('has fixtures', () => expect(fixtures.length).toBeGreaterThanOrEqual(3))

  it.each(fixtures)('%s: text ≥ 97 %, chords on the right syllable ≥ 90 %', async (name) => {
    const truth = readFileSync(join(FIXTURES, `${name}.truth.txt`), 'utf8').trimEnd()
    const psm = process.env.OCR_PSM
    const pagePsm = OCR_PAGE_PARAMS.tessedit_pageseg_mode
    const engine: TesseractWorkerLike = {
      setParameters: (p) =>
        worker.setParameters(
          (psm && p.tessedit_pageseg_mode === pagePsm
            ? { ...p, tessedit_pageseg_mode: psm }
            : p) as Partial<WorkerParams>
        ),
      recognize: (img, options, output) => worker.recognize(img as Buffer, options, output)
    }
    const t0 = performance.now()
    const page = await ocrPage(engine, readRgba(join(FIXTURES, `${name}.png`)), encodePng)
    const ms = performance.now() - t0
    const { text, uncertain } = wordsToText(page.words)
    const textAcc = textAccuracy(text, truth)
    const chords = chordAccuracy(text, truth)
    console.log(
      `[ocr] ${name}: text ${(textAcc * 100).toFixed(2)} %, chords ${(chords.score * 100).toFixed(2)} %` +
        ` (${chordsWithPositions(truth).chords.length} chords), skew ${page.skewDeg}°, ${Math.round(ms)} ms` +
        (chords.missed.length ? `\n[ocr]   missed chords: ${chords.missed.join(', ')}` : '') +
        (uncertain.length ? `\n[ocr]   uncertain: ${uncertain.map((u) => u.text).join(' ')}` : '')
    )
    if (process.env.OCR_SHOW) console.log(text)
    expect(textAcc).toBeGreaterThanOrEqual(TEXT_TARGET)
    expect(chords.score).toBeGreaterThanOrEqual(CHORD_TARGET)
  })
})
